import { create } from 'zustand'
import { useGameState } from './StoryStore';
import { Edge, Node } from '@xyflow/react';
import { Story } from '../model/story';

export type PlayGraph = {
    nodes: Node[];
    edges: Edge[];
}

export type PlayState = {
    currentNode: string;
    visitedNodes: Set<string>;
    visitedTransitions: Set<string>;
    // sequence of transitions
    currentPath: string[];
    graph: PlayGraph;
    numberOfTravels: number;
    isDead: boolean;
};

export type Actions = {
    isOnPath: (nodeId: string) => boolean;
    visitNode: (nodeId: string) => void;
    selectTransition: (transitionId: string) => void;
    reset: () => void;
}

export function displayGraph(story: Story,
    state: {
        visitedNodes: Set<string>;
        visitedTransitions: Set<string>;
        currentPath: string[],
        currentNode: string;
    }
): PlayGraph {
    const storyNodes = Object.values(story.nodes);

    // Transform GameState into graph representation
    // @ts-ignore (not sure why ts-ignore is needed here)
    const nodes: Node[] = storyNodes.filter((n) => state.visitedNodes.has(n.id)).map(
        (storyNode) => {
            const isCurrent = storyNode.id === state.currentNode;
            let background = "#fff";
            if (storyNode.death) {
                background = "#ffe6e6";
            } else if (isCurrent) {
                background = "#e0f0ff";
            }
            return {
                id: storyNode.id,
                data: { label: storyNode.title },
                position: storyNode.position,
                targetPosition: 'left',
                sourcePosition: 'right',

                style: {
                    border: isCurrent ? '3px solid #4880bc' : '1px solid #222138',
                    padding: 10,
                    background,
                },
            }
        });

    const edges: Edge[] = [];
    Object.values(story.transitions).filter((t) => state.visitedTransitions.has(t.id)).
        forEach((transition) => {
            const isCurrent = state.currentPath.includes(transition.id);
            edges.push({
                id: transition.id,
                source: transition.source,
                target: transition.target,
                animated: isCurrent,
                label: transition.label,
                style: {
                    stroke: isCurrent ? '#4880bc' : '#222138',
                    strokeWidth: isCurrent ? 2 : 2,
                },
                markerEnd: {
                    type: 'arrowclosed',
                    width: 10,
                    height: 10,
                    color: '#222138',
                },
            });

        });

    return { nodes, edges };
}

function backtrackPath(node: string, visitedTransitions: Set<string>): string[] {
    const story = useGameState.getState().story;
    const transitions = Object.keys(story.transitions);

    const path: string[] = [];
    let currentNodeId = node;

    while (true) {

        // Find a transition that was visited leading to this node
        const foundTransition = transitions.find((transitionId) => {
            const transition = story.transitions[transitionId];
            return transition.target === currentNodeId && visitedTransitions.has(transitionId);
        });

        if (!foundTransition) break;

        path.unshift(foundTransition);
        currentNodeId = story.transitions[foundTransition].source;
    }


    return path;
}

function printPath(path: string[]) {
    const story = useGameState.getState().story;
    console.log("Current Path:");
    for (const t_id of path) {
        const t = story.transitions[t_id];
        console.log(`  Transition ${t_id}: ${t.source} -> ${t.target}`);
    }
}

export function getInitialPlayState(): PlayState {
    const currentNode = useGameState.getState().story.startingNode;
    const visitedNodes = new Set<string>();
    visitedNodes.add(currentNode);
    const visitedTransitions = new Set<string>();
    for (const [id, transition] of Object.entries(useGameState.getState().story.transitions)) {
        if (transition.source === currentNode || transition.startingVisible) {
            visitedTransitions.add(id);
            visitedNodes.add(transition.source);
        }
    }
    const currentPath = backtrackPath(currentNode, visitedTransitions);

    const playGraph = displayGraph(useGameState.getState().story,
        { visitedNodes, visitedTransitions, currentPath, currentNode }
    );

    return {
        currentNode: currentNode,
        visitedNodes: visitedNodes,
        visitedTransitions: visitedTransitions,
        graph: playGraph,
        currentPath,
        numberOfTravels: 0,
        isDead: false,

    }
}

function _isOnPath(state: PlayState, nodeId: string): boolean {
    const story = useGameState.getState().story;
    for (const ts_id of state.currentPath) {
        const transition = story.transitions[ts_id];
        if (transition.source === nodeId || transition.target === nodeId) {
            return true;
        }
    }
    return false;
}

export const usePlayState = create<PlayState & Actions>((set) => {
    const initialState = getInitialPlayState();


    return {
        ...initialState,

        reset: () => {
            const initialState = getInitialPlayState();
            set(() => initialState);
        },

        visitNode: (nodeId: string) =>
            set((state) => {
                if (!_isOnPath(state, nodeId)) {
                    return {};
                }

                const node = useGameState.getState().story.nodes[nodeId];
                const isDead = node.death === true;

                const newVisitedNodes = new Set(state.visitedNodes);
                newVisitedNodes.add(nodeId);
                return {
                    visitedNodes: newVisitedNodes,
                    currentNode: nodeId,
                    numberOfTravels: state.numberOfTravels + 1,
                    isDead: isDead,
                    graph: displayGraph(useGameState.getState().story, {
                        visitedNodes: newVisitedNodes,
                        visitedTransitions: state.visitedTransitions,
                        currentPath: state.currentPath,
                        currentNode: nodeId
                    }),
                };
            }),

        isOnPath: (nodeId: string): boolean => {
            return _isOnPath(usePlayState.getState(), nodeId);
        },

        selectTransition: (transitionId: string) =>
            set((state) => {
                const transition = useGameState.getState().transitionFromId(transitionId);

                const newVisitedTransitions = new Set(state.visitedTransitions);
                newVisitedTransitions.add(transitionId);
                const visitedNodes = new Set(state.visitedNodes);
                visitedNodes.add(transition.source);
                visitedNodes.add(transition.target);

                const pathIndex = state.currentPath.indexOf(transitionId);
                if (pathIndex !== -1) {
                    throw new Error(`Transition ${transitionId} is already in the current path.`);
                }
                let newCurrentPath: string[];
                newCurrentPath = state.currentPath.slice(0, pathIndex + 1);
                newCurrentPath.push(transitionId);

                const targetNode = useGameState.getState().story.nodes[transition.target];
                const isDead = targetNode.death === true;

                return {
                    visitedTransitions: newVisitedTransitions,
                    currentNode: transition.target,
                    visitedNodes: visitedNodes,
                    numberOfTravels: state.numberOfTravels + 1,
                    currentPath: newCurrentPath,
                    isDead: isDead,
                    graph: displayGraph(useGameState.getState().story, {
                        visitedNodes: visitedNodes,
                        visitedTransitions: newVisitedTransitions,
                        currentPath: newCurrentPath,
                        currentNode: transition.target
                    }),

                };
            }),
    }
});
