import { create } from 'zustand'
import { isStory, SpaceTimeLocation, Story, StoryNode, Transition } from '../model/story'
import { getStoryById, StoryId } from '../stories'
import { Edge, Node } from '@xyflow/react';
import dagre from 'dagre';
import { persist } from 'zustand/middleware';

/// Generate a UUID
function newId(): string {
    // We still need 8 bytes (64 bits) of entropy
    const array = new Uint8Array(8);
    crypto.getRandomValues(array);

    // Define the human-friendly alphabet (Crockford)
    const alphabet = "0123456789abcdefghjkmnpqrstvwxyz";

    // Convert the byte array to a BigInt to handle the bitwise math
    let value = 0n;
    for (const byte of array) {
        value = (value << 8n) | BigInt(byte);
    }

    // Encode the BigInt into Base32 characters
    let result = "";
    for (let i = 0; i < 13; i++) {
        const index = Number(value & 0x1Fn); // Get last 5 bits
        result = alphabet[index] + result;
        value >>= 5n; // Shift right by 5 bits
    }

    return result;
}

export type Selected = {
    kind: 'node' | 'transition';
    id: string;
}

// Define types for state & actions
export type StoryState = {
    storyId: StoryId;
    currentNodeId?: Selected;
    displayGraph: TimeGraph;
    story: Story;
    // List of transitions with the node key as source
    nodeTransitions: Record<string, string[]>;
}

export type NodeAttributes = {
    title: string;
    description: string;
    coord: SpaceTimeLocation;
    position: { x: number; y: number; };
    death: boolean;
}

export type TransitionAttributes = {
    label: string;
    description?: string;
    startingVisible: boolean;
}

export type Actions = {
    setStoryId: (storyId: string) => void;
    setStartingNode: (nodeId: string) => void;

    setCurrentNodeId: (selected?: Selected) => void;
    addNode: (attrs?: Partial<NodeAttributes>) => string;
    addTransition: (sourceNodeId: string, targetNodeId: string) => string;
    reset: () => void;
    clear: () => void;

    transitionFromId(id: string): Transition;

    setNodeAttributes(nodeId: string, attributes: Partial<NodeAttributes>): void;
    setTransitionAttributes(transitionId: string, attributes: Partial<TransitionAttributes>): void;

    removeNode(nodeId: string): void;
    removeTransition(transitionId: string): void;

    layoutGraph: () => void;
}



type TimeGraph = {
    nodes: Node[];
    edges: Edge[];
}

function layout(graph: TimeGraph): TimeGraph {

    const dagreGraph = new dagre.graphlib.Graph();
    dagreGraph.setDefaultEdgeLabel(() => ({}));

    // Set the direction to 'LR' (Left to Right)
    dagreGraph.setGraph({ rankdir: 'LR' });

    graph.nodes.forEach((node) => {
        dagreGraph.setNode(node.id, { width: 150, height: 50 });
    });

    graph.edges.forEach((edge) => {
        dagreGraph.setEdge(edge.source, edge.target);
    });

    dagre.layout(dagreGraph);

    // @ts-ignore
    const nodes: Node[] = graph.nodes.map((node) => {
        const nodeWithPosition = dagreGraph.node(node.id);
        return {
            ...node,
            targetPosition: 'left',
            sourcePosition: 'right',
            // Dagre calculates from the center, React Flow from top-left
            position: {
                x: nodeWithPosition.x - 75,
                y: nodeWithPosition.y - 25,
            },
        };
    });

    return { nodes, edges: graph.edges };
}

function storyNodeToDisplayNode(storyNode: StoryNode, isCurrent: boolean): Node {
    return {
        id: storyNode.id,
        data: { label: storyNode.title },
        targetPosition: 'left',
        sourcePosition: 'right',
        position: storyNode.position || { x: 0, y: 0 },
        style: {
            background: isCurrent ? '#fffae6' : '#fff',
            border: isCurrent ? '2px solid #f39c12' : '1px solid #222138',
            width: 50,
            height: 50,
            textAlign: 'center',
            paddingTop: 15,
        },
    }
}

function transitionToEdge(transition: Transition, isCurrent: boolean): Edge {
    return {
        id: transition.id,
        source: transition.source,
        target: transition.target,
        animated: false,
        label: transition.label,
        style: { stroke: isCurrent ? "#f39c12" : '#222138', strokeWidth: 2 },
        markerEnd: {
            type: 'arrowclosed',
            width: 20,
            height: 20,
            color: '#222138',
        },
    }
}

export function displayGraph(story: Story, state: { currentNodeId?: string }): TimeGraph {
    const storyNodes = Object.values(story.nodes);

    // Transform GameState into graph representation
    // @ts-ignore (should be fine)
    const nodes: Node[] = storyNodes.map((storyNode) => {
        const isCurrent = state.currentNodeId === storyNode.id;
        return storyNodeToDisplayNode(storyNode, isCurrent);
    });

    const edges: Edge[] = [];
    Object.values(story.transitions).forEach((transition) => {
        const isCurrent = state.currentNodeId === transition.id;
        edges.push(transitionToEdge(transition, isCurrent));
    });

    return { nodes, edges };
}

function computeNodeTransitions(story: Story): Record<string, string[]> {
    const nodeTransitions = {} as Record<string, string[]>;
    Object.values(story.transitions).forEach((transition) => {
        if (!nodeTransitions[transition.source]) {
            nodeTransitions[transition.source] = [];
        }
        nodeTransitions[transition.source].push(transition.id);
    });
    return nodeTransitions;
}

function getInitialState(id: StoryId): StoryState {

    const story = getStoryById(id);
    if (!isStory(story)) {
        throw new Error("Invalid story schema");
    }


    const graph: TimeGraph = displayGraph(story, {});

    return {
        storyId: 'monkeys12',
        currentNodeId: undefined,
        story: story,
        displayGraph: graph,
        nodeTransitions: computeNodeTransitions(story),
    };


}


// Create store using the curried form of `create`
export const useGameState = create<StoryState & Actions>()(
    persist(
        (set) => {

            const state = getInitialState('btf');

            return {
                ...state,

                reset: () => set((state) => getInitialState(state.storyId)),

                setStoryId: (storyId: string) => set(() => {
                    const newState = getInitialState(storyId as StoryId);
                    return {
                        ...newState
                    };
                }),

                setStartingNode: (nodeId: string) => set((state) => {
                    const updatedStory: Story = {
                        ...state.story,
                        startingNode: nodeId
                    };
                    return {
                        story: updatedStory
                    };
                }),

                layoutGraph: () => set((state) => {
                    const laidOutGraph = layout(state.displayGraph);
                    const updatedNodes = laidOutGraph.nodes.reduce((acc, node) => {
                        const storyNode = state.story.nodes[node.id];
                        if (storyNode) {
                            acc[node.id] = {
                                ...storyNode,
                                position: node.position
                            };
                        }
                        return acc;
                    }, {} as Record<string, StoryNode>);

                    const updatedStory: Story = {
                        ...state.story,
                        nodes: updatedNodes
                    };
                    return {
                        story: updatedStory,
                        displayGraph: laidOutGraph
                    };
                }),

                clear: () => set(() => {
                    const emptyStory: Story = {
                        id: `story-${newId()}`,
                        title: 'New Story',
                        startingNode: 'start',
                        nodes: {
                            "start": {
                                id: "start",
                                title: "Starting Node",
                                description: "[Description here]",
                                coord: { year: 2000, month: 1, day: 1, time: "12:00" },
                                position: { x: 0, y: 0 }
                            }
                        },
                        transitions: {}
                    };
                    return {
                        storyId: emptyStory.id,
                        currentNodeId: undefined,
                        story: emptyStory,
                        displayGraph: displayGraph(emptyStory, {}),
                        nodeTransitions: {}
                    };
                }),
                setCurrentNodeId: (selected?: Selected) => set((state) => {
                    return { currentNodeId: selected, displayGraph: displayGraph(state.story, { currentNodeId: selected?.id }) };
                }),
                getSortedPath: (): Transition[] => {
                    const path: Transition[] = [];
                    // Get current path based on selected transitions

                    return path;

                },
                addNode: (attrs?: Partial<NodeAttributes>): string => {
                    const newNodeId = `n-${newId()}`;
                    set((state) => {
                        const newNode: StoryNode = {
                            id: newNodeId,
                            title: 'New Node',
                            description: '[Description here]',
                            coord: { year: 2000, month: 1, day: 1, time: '12:00' },
                            position: { x: 0, y: 0 },
                            ...attrs
                        };
                        const updatedStory: Story = {
                            ...state.story,
                            nodes: {
                                ...state.story.nodes,
                                [newNodeId]: newNode
                            }
                        };
                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, { currentNodeId: state.currentNodeId?.id }),
                        };
                    });
                    return newNodeId;
                },

                addTransition: (sourceNodeId: string, targetNodeId: string): string => {
                    const newTransitionId = `ts-${newId()}`;
                    set((state) => {
                        const newTransition: Transition = {
                            id: newTransitionId,
                            label: 'New Choice',
                            source: sourceNodeId,
                            target: targetNodeId,
                            startingVisible: false,
                            description: '[Description here]',
                        };
                        const updatedStory: Story = {
                            ...state.story,
                            transitions: {
                                ...state.story.transitions,
                                [newTransitionId]: newTransition
                            }
                        };
                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, {}),
                            nodeTransitions: computeNodeTransitions(updatedStory)
                        };
                    });
                    return newTransitionId;
                },

                setNodeAttributes: (nodeId: string, attributes: Partial<NodeAttributes>) => {
                    set((state) => {
                        const node = state.story.nodes[nodeId];
                        if (!node) {
                            throw new Error("Node not found");
                        }
                        const updatedNode: StoryNode = {
                            ...node,
                            ...attributes,
                        };
                        const updatedStory: Story = {
                            ...state.story,
                            nodes: {
                                ...state.story.nodes,
                                [nodeId]: updatedNode
                            }
                        };


                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, { currentNodeId: state.currentNodeId?.id })
                        };
                    });
                },

                setTransitionAttributes: (transitionId: string, attributes: Partial<TransitionAttributes>) => {
                    set((state) => {
                        const transition = state.story.transitions[transitionId];
                        if (!transition) {
                            throw new Error("Transition not found");
                        }
                        const updatedTransition: Transition = {
                            ...transition,
                            ...attributes,
                        };
                        const updatedStory: Story = {
                            ...state.story,
                            transitions: {
                                ...state.story.transitions,
                                [transitionId]: updatedTransition
                            }
                        };
                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, { currentNodeId: state.currentNodeId?.id }),
                        };
                    });
                },

                removeNode: (nodeId: string) => {
                    set((state) => {
                        const updatedNodes = { ...state.story.nodes };
                        delete updatedNodes[nodeId];

                        // Also remove associated transitions
                        const updatedTransitions = Object.fromEntries(
                            Object.entries(state.story.transitions).filter(
                                ([, transition]) => transition.source !== nodeId && transition.target !== nodeId
                            )
                        );

                        const updatedStory: Story = {
                            ...state.story,
                            nodes: updatedNodes,
                            transitions: updatedTransitions
                        };
                        const currentNodeId = state.currentNodeId?.id === nodeId ? undefined : state.currentNodeId;

                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, { currentNodeId: state.currentNodeId?.id }),
                            nodeTransitions: computeNodeTransitions(updatedStory),
                            currentNodeId
                        };
                    });
                },

                removeTransition: (transitionId: string) => {
                    set((state) => {
                        const updatedTransitions = { ...state.story.transitions };
                        delete updatedTransitions[transitionId];
                        const updatedStory: Story = {
                            ...state.story,
                            transitions: updatedTransitions
                        };
                        const currentNodeId = state.currentNodeId?.id === transitionId ? undefined : state.currentNodeId;

                        return {
                            story: updatedStory,
                            displayGraph: displayGraph(updatedStory, { currentNodeId: state.currentNodeId?.id }),
                            nodeTransitions: computeNodeTransitions(updatedStory),
                            currentNodeId
                        };
                    });
                },

                transitionFromId(id: string): Transition {
                    const transition = useGameState.getState().story.transitions[id];
                    if (!transition) {
                        throw new Error("Transition not found");
                    }
                    return transition;
                }

            }
        },

        {
            name: 'timegame-storage',
        })
);

// @ts-ignore
window.store = useGameState;