import { usePlayState } from "../stores/PlayStore";
import { useGameState } from "../stores/StoryStore";

function TransitionInfo({ id }: { id: string }) {
    const transition = useGameState((state) => state.story.transitions[id]);
    const isCurrent = usePlayState((state) => state.currentPath.includes(id));

    const onSelectTransition = () => {
        usePlayState.getState().selectTransition(id);
    };

    if (!transition) {
        throw new Error("Transition not found");
    }

    return <div>
        <h2>{transition.label}</h2>
        <div>{transition.description}</div>
        <button onClick={onSelectTransition}
            style={{ backgroundColor: isCurrent ? '#4880bc' : '#ddd', color: isCurrent ? 'white' : 'black' }}>
            PICK
        </button>
        <div style={{ fontSize: 10, textAlign: 'right' }}>
            {transition.id}
        </div>
    </div>;
}

export function CurrentNode() {
    const currentNodeId = usePlayState((state) => state.currentNode);
    const currentNode = useGameState((state) => state.story.nodes[currentNodeId]);
    const nodeTransitions = useGameState((state) => state.nodeTransitions[currentNodeId]);

    if (!currentNode) {
        return <div>No current node selected.</div>;
    }

    return (
        <div>
            <h2>Current Node</h2>
            <p><strong>Title:</strong> {currentNode.title}</p>
            <p><strong>Description:</strong> {currentNode.description}</p>
            {nodeTransitions && nodeTransitions.length > 0 ? (
                <div>
                    {nodeTransitions.map((id) => (
                        <TransitionInfo key={id} id={id} />
                    ))}
                </div >
            ) : (
                <p>No choices available from this node.</p>
            )
            }
        </div>
    );
}