import { ChangeEvent, useCallback } from "react";
import { SpaceTimeLocation, StoryNode } from "../model/story";
import { useGameState } from "../stores/StoryStore";



export function TransitionEditor({ id }: { id: string }) {
    const transition = useGameState((state) => state.story.transitions[id]);
    const setTransitionAttributes = useGameState((state) => state.setTransitionAttributes);

    const onLabelChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
        setTransitionAttributes(id, { label: e.target.value });
    }, [id, setTransitionAttributes]);

    const onDescriptionChange = useCallback((e: ChangeEvent<HTMLTextAreaElement>) => {
        setTransitionAttributes(id, { description: e.target.value });
    }, [id, setTransitionAttributes]);

    const onStartingVisibilityChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
        setTransitionAttributes(id, { startingVisible: e.target.checked });
    }, [id, setTransitionAttributes]);

    const targetName = useGameState((state) => {
        const targetNode = state.story.nodes[transition.target];
        return targetNode ? targetNode.title : 'Unknown Node';
    });
    const sourceName = useGameState((state) => {
        const sourceNode = state.story.nodes[transition.source];
        return sourceNode ? sourceNode.title : 'Unknown Node';
    });

    const removeTransition = useGameState((state) => state.removeTransition);

    const onRemove = useCallback(() => {
        removeTransition(id);
    }, [id, removeTransition]);


    if (!transition) {
        return <div>Transition not found</div>;
    }

    return (
        <div style={{ border: "1px solid #ddd", padding: 8, marginBottom: 8 }}>
            <div style={{ fontSize: 10 }}>
                {transition.id}
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                <strong>{sourceName} → {targetName}</strong>
            </div>
            <label style={{ marginLeft: "auto" }}>
                Starting Visible
                <input
                    type="checkbox"
                    checked={transition.startingVisible || false}
                    onChange={onStartingVisibilityChange}
                    style={{ marginLeft: 4 }}
                />
            </label>
            <button onClick={onRemove} style={{ float: "right" }}>Remove</button>
            <div style={{ marginTop: 8 }}>
                <label>
                    Label
                    <input
                        type="text"
                        value={transition.label}
                        onChange={onLabelChange}
                        style={{ width: "100%", marginTop: 4 }}
                    />
                </label>
            </div>
            <div style={{ marginTop: 8 }}>
                <label>
                    Description
                    <textarea
                        value={transition.description || ""}
                        onChange={onDescriptionChange}
                        rows={3}
                        style={{ width: "100%", marginTop: 4 }}
                    />
                </label>
            </div>
        </div>
    );
}

function CoordEditor({ coord, nodeId }: { coord: SpaceTimeLocation; nodeId: string }) {
    const setNodeAttributes = useGameState((state) => state.setNodeAttributes);

    const updateCoord = useCallback(<K extends keyof SpaceTimeLocation>(key: K, value: SpaceTimeLocation[K]) => {
        setNodeAttributes(nodeId, { coord: { ...coord, [key]: value } });
    }, [coord, nodeId, setNodeAttributes]);

    const onNumber = (key: keyof SpaceTimeLocation) => (e: ChangeEvent<HTMLInputElement>) => {
        const v = e.target.value;
        const num = v === "" ? 0 : Number(v);
        updateCoord(key as any, num as any);
    };

    const onString = (key: keyof SpaceTimeLocation) => (e: ChangeEvent<HTMLInputElement>) => {
        updateCoord(key as any, e.target.value as any);
    };

    return (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 12 }}>
            <label>
                Year
                <input type="number" value={coord.year} onChange={onNumber("year")} style={{ width: "100%", marginTop: 4 }} />
            </label>
            <label>
                Month
                <input type="number" min={1} max={12} value={coord.month} onChange={onNumber("month")} style={{ width: "100%", marginTop: 4 }} />
            </label>
            <label>
                Day
                <input type="number" min={1} max={31} value={coord.day} onChange={onNumber("day")} style={{ width: "100%", marginTop: 4 }} />
            </label>
            <label>
                Time
                <input type="text" value={coord.time || ""} onChange={onString("time")} style={{ width: "100%", marginTop: 4 }} />
            </label>
        </div>
    );
}

export default function NodeEdit({ id }: { id: string }) {
    const currentNodeId = id;
    const currentNode = useGameState((state) => state.story.nodes[currentNodeId]);
    const nodeTransitions = useGameState((state) => state.nodeTransitions[currentNodeId]);
    const setNodeAttributes = useGameState((state) => state.setNodeAttributes);

    const onTitleChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
        if (!currentNodeId) return;
        setNodeAttributes(currentNodeId, { title: e.target.value });
    }, [currentNodeId, setNodeAttributes]);

    const onDescriptionChange = useCallback((e: ChangeEvent<HTMLTextAreaElement>) => {
        if (!currentNodeId) return;
        setNodeAttributes(currentNodeId, { description: e.target.value });
    }, [currentNodeId, setNodeAttributes]);

    const addNodeFromHere = useCallback(() => {
        const state = useGameState.getState();
        const myPosition = state.story.nodes[currentNodeId].position || { x: 0, y: 0 };

        const newNodeId = state.addNode({ title: "New Title" });
        state.setNodeAttributes(newNodeId, { position: { x: myPosition.x + 200, y: myPosition.y } });
        state.addTransition(currentNodeId, newNodeId);
    }, [currentNodeId]);

    const onRemoveNode = () => {
        useGameState.getState().removeNode(currentNodeId);
    };

    const setDead = (ev: ChangeEvent<HTMLInputElement>) => {
        useGameState.getState().setNodeAttributes(currentNodeId, { death: ev.target.checked });
    };

    const onSetThisAsStarting = () => {
        useGameState.getState().setStartingNode(currentNodeId);
    };
    const startingNodeId = useGameState((state) => state.story.startingNode);
    const isStartingNode = startingNodeId === currentNodeId;

    return (
        <div>
            <h2>Edit Node</h2>
            <button onClick={onRemoveNode} style={{ float: "right" }}>Remove Node</button>
            <button onClick={onSetThisAsStarting} style={{ float: "right", marginRight: 8 }}>
                {isStartingNode ? "★ Starting Node" : "Set as Starting Node"}
            </button>
            <label style={{ display: "block", marginBottom: 12 }}>
                <input type="checkbox" checked={currentNode?.death || false} onChange={setDead} />
                Mark as Death
            </label>
            <div style={{ marginBottom: 12 }}>
                <label>
                    Title
                    <input
                        type="text"
                        value={currentNode ? currentNode.title : ""}
                        onChange={onTitleChange}
                        style={{ width: "100%", marginTop: 4 }}
                    />
                </label>
            </div>
            <div style={{ marginBottom: 12 }}>
                <label>
                    Description
                    <textarea
                        value={(currentNode && currentNode.description) || ""}
                        onChange={onDescriptionChange}
                        rows={4}
                        style={{ width: "100%", marginTop: 4 }}
                    />
                </label>
            </div>
            {currentNode && (
                <div style={{ marginBottom: 16 }}>
                    <h3>Coordinates</h3>
                    <CoordEditor coord={currentNode.coord} nodeId={currentNode.id} />
                </div>
            )}

            <div>
                <h3>Transitions from this node</h3>
                <button onClick={addNodeFromHere} style={{ marginBottom: 8 }}>Add Choice to New Node</button>
                {nodeTransitions && nodeTransitions.length > 0 ? (
                    nodeTransitions.map((id) => <TransitionEditor key={id} id={id} />)
                ) : (
                    <p>No transitions available from this node.</p>
                )}
            </div>
        </div>
    );
}

export function SelectedEdit() {
    const selected = useGameState((state) => state.currentNodeId);
    const nodeId = selected?.kind === 'node' ? selected?.id : null;
    const transitionId = selected?.kind === 'transition' ? selected?.id : null;


    return <>
        {nodeId && <NodeEdit id={nodeId} />}
        {transitionId && <TransitionEditor id={transitionId} />}
    </>
}