import { useCallback } from 'react';
import { ReactFlow, Edge, Node, MiniMap, Controls, Background } from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import styled from 'styled-components';
import { usePlayState } from '../stores/PlayStore';


const GraphContainer = styled.div`
  width: 100%;
  height: 100%;
  border: 1px solid #eee;
  background: #f9f9f9;

  /* Custom styling for the nodes to make them circles */
  .react-flow__node {
    border-radius: 50%;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
  }
`;

export function StoryBoard() {
  // const graph = useGameState((state) => state.displayGraph);
  const graph = usePlayState((state) => state.graph);
  const visitNode = usePlayState((state) => state.visitNode);

  const onEdgeClick = useCallback((event: React.MouseEvent, edge: Edge) => {
    console.log("Edge clicked:", edge.id);
  }, []);

  const onNodeClick = useCallback((event: React.MouseEvent, node: Node) => {
    visitNode(node.id);
  }, []);

  return <GraphContainer>
    <ReactFlow
      nodes={graph.nodes}
      edges={graph.edges}
      onEdgeClick={onEdgeClick}
      onNodeClick={onNodeClick}

      fitView
    >
      <Controls />
      <Background />
    </ReactFlow>

  </GraphContainer>
}