import { z } from 'zod';

export const SpaceTimeLocationSchema = z.object({
    year: z.number().int(),
    month: z.number().int().min(1).max(12),
    day: z.number().int().min(1).max(31),
    time: z.string().optional(),
    y: z.number().optional(),
});

export const TransitionSchema = z.object({
    id: z.string(),
    label: z.string(),
    startingVisible: z.boolean(),
    description: z.string(),
    source: z.string(),
    target: z.string(),
});

export const StoryNodeSchema = z.object({
    id: z.string(),
    title: z.string(),
    description: z.string(),
    coord: SpaceTimeLocationSchema,
    death: z.boolean().default(false),
    position: z.object({ x: z.number(), y: z.number() }),
});

export const StorySchema = z.object({
    id: z.string(),
    title: z.string(),
    startingNode: z.string(),
    nodes: z.record(z.string(), StoryNodeSchema),
    transitions: z.record(z.string(), TransitionSchema),
});

export type SpaceTimeLocation = z.infer<typeof SpaceTimeLocationSchema>;
export type Transition = z.infer<typeof TransitionSchema>;
export type StoryNode = z.infer<typeof StoryNodeSchema>;
export type Story = z.infer<typeof StorySchema>;

export function isStory(data: unknown): data is Story {
    const result = StorySchema.safeParse(data);
    return result.success;
}

